#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> edges(m, vector<long long>(2));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> edges[i][j];
        }
    }

    vector<vector<int>> adj(n + 1);
    for (const vector<long long>& e : edges) adj[e[0]].push_back((int)e[1]);
    vector<char> seen(n + 1, 0);
    seen[1] = 1;
    vector<int> stack = {1};
    long long visited = 1;
    while (!stack.empty()) {
        int room = stack.back();
        stack.pop_back();
        for (int key : adj[room]) {
            if (!seen[key]) {
                seen[key] = 1;
                visited++;
                stack.push_back(key);
            }
        }
    }
    cout << (visited == n ? "yes" : "no") << "\n";

    return 0;
}

